            id: id.to_string(),
            title: title.unwrap_or(id).to_string(),
            url: url.map(str::to_string),
            path: path.to_path_buf(),
            normalised: pieces.join(" "),
            pages,
            sections,
            marked_up,
            statements,
            displays,

